<?php use App\Support\App;App::requireAdmin();$rows=App::db()->query('SELECT u.id,u.name,u.email,u.phone,u.role,u.balance,u.status,l.name level_name,u.created_at FROM users u LEFT JOIN user_levels l ON l.id=u.level_id ORDER BY u.id DESC LIMIT 300')->fetchAll();$title='Users';require __DIR__.'/../layouts/head.php';require __DIR__.'/../components/app_start.php';?><div><h1 class="page-title">Users</h1><p class="page-sub">Akun, nomor WhatsApp, level dan saldo pengguna.</p></div><div class="saas-card mt-6 overflow-auto"><table class="w-full text-sm min-w-[850px]"><thead><tr><th>User</th><th>WhatsApp</th><th>Level</th><th>Role</th><th>Balance</th><th>Status</th><th>Joined</th></tr></thead><tbody><?php foreach($rows as $r):?><tr class="border-t" style="border-color:var(--line)"><td><b><?=htmlspecialchars($r['name'])?></b><div class="text-xs text-zinc-500"><?=htmlspecialchars($r['email'])?></div></td><td><?=htmlspecialchars($r['phone']?:'-')?></td><td><span class="badge"><?=htmlspecialchars($r['level_name']??'-')?></span></td><td><?=htmlspecialchars($r['role'])?></td><td class="font-semibold">Rp<?=number_format($r['balance'],0,',','.')?></td><td><span class="badge"><?=htmlspecialchars($r['status'])?></span></td><td><?=htmlspecialchars($r['created_at'])?></td></tr><?php endforeach?></tbody></table></div><?php require __DIR__.'/../components/app_end.php';require __DIR__.'/../layouts/foot.php';?>